INSERT INTO chat_message (session_id, role, content, sources)
SELECT s.id, 'ASSISTANT', '', '[]'::jsonb
FROM chat_session s
WHERE s.id = #{sessionId}
  AND s.user_id = #{userId}
RETURNING id

WITH deleted AS (
    DELETE FROM chat_message m
    USING chat_session s
    WHERE m.id = #{messageId}
      AND m.session_id = #{sessionId}
      AND s.id = m.session_id
      AND s.user_id = #{userId}
      AND m.role = 'ASSISTANT'
      AND m.content = ''
    RETURNING m.id
)
SELECT EXISTS(SELECT 1 FROM deleted)

SELECT recent.role, recent.content
FROM (
    SELECT m.role, m.content, m.created_at, m.id
    FROM chat_message m
    JOIN chat_session s ON s.id = m.session_id
    WHERE m.session_id = #{sessionId}
      AND s.user_id = #{userId}
      AND NOT (m.role = 'ASSISTANT' AND m.content = '')
    ORDER BY m.created_at DESC, m.id DESC
    LIMIT #{limit}
) recent
ORDER BY recent.created_at ASC, recent.id ASC

SELECT m.id, m.session_id, m.role, m.content, m.sources, m.created_at
FROM chat_message m
JOIN chat_session s ON s.id = m.session_id
WHERE m.session_id = #{sessionId}
  AND s.user_id = #{userId}
  AND NOT (m.role = 'ASSISTANT' AND m.content = '')
ORDER BY m.created_at DESC, m.id DESC
LIMIT #{fetchLimit}

SELECT m.id, m.session_id, m.role, m.content, m.sources, m.created_at
FROM chat_message m
JOIN chat_session s ON s.id = m.session_id
WHERE m.id = #{messageId}
  AND m.session_id = #{sessionId}
  AND s.user_id = #{userId}
  AND m.role = 'ASSISTANT'
  AND m.content <> ''
